'use client';
import {useIsMobile} from "@/src/hooks/useIsMobile";
import {useRef, useState} from "react";

import { Home, FolderOpen, Mail, User } from "lucide-react";
import Image from "next/image";

/* TODO: Manually polish Navbar generated by AI */

const links = [
    { label: "Home", href: "/", icon: Home, column: "col-start-1" },
    { label: "Projects", href: "/projects", icon: FolderOpen, column: "col-start-2" },
    { label: "Contact", href: "/contact", icon: Mail, column: "col-start-4" },
    { label: "About Me", href: "/about", icon: User, column: "col-start-5" },
];

export default function Navbar() {
    const isMobile = useIsMobile();

    return (
        <header
            className={`
                z-50 bg-foreground/10 backdrop-blur-lg
                shadow-md shadow-foreground/10
                ${isMobile
                ? "fixed inset-x-0 bottom-0 border-t border-stone-200/80"
                : "sticky top-0"
            }
            `}
            style={isMobile
                ? { paddingBottom: "env(safe-area-inset-bottom)" }
                : undefined
            }
        >
            {!isMobile && (
                <div className="h-px w-full bg-linear-to-r from-transparent via-orange-400/50 to-transparent" />
            )}

            <nav
                aria-label="Main navigation"
                className={`
                    mx-auto w-full items-center
                    ${isMobile
                    ? "grid grid-cols-5 px-2 py-2"
                    : "flex gap-8 px-5 py-4 md:px-8"
                }
                `}
            >
                <a
                    href="/"
                    aria-label="Home"
                    className={`
                        flex items-center justify-center rounded-lg
                        focus-visible:outline-2 focus-visible:outline-orange-500
                        ${isMobile
                        ? "col-start-3 row-start-1 justify-self-center"
                        : "mr-auto shrink-0"
                    }
                    `}
                >
                    <Image
                        src="/MattCreationsMinimalistLogo.png"
                        alt="Logo"
                        width={128}
                        height={64}
                        className={isMobile ? "h-18 w-20 object-contain" : "h-14 w-auto"}
                    />
                </a>

                {links.map(({ label, href, icon: Icon, column }) => (
                    <a
                        key={label}
                        href={href}
                        className={`
                            flex items-center justify-center rounded-lg
                            text-foreground transition-colors
                            hover:bg-orange-50 hover:text-orange-600
                            focus-visible:outline-2 focus-visible:outline-orange-500
                            ${isMobile
                            ? `${column} row-start-1 min-h-12 flex-col gap-1 py-1 text-[10px]`
                            : "px-3 py-2 text-sm font-medium"
                        }
                        `}
                    >
                        {isMobile && (
                            <Icon
                                aria-hidden="true"
                                className="h-5 w-5 shrink-0"
                            />
                        )}
                        <span className="whitespace-nowrap">{label}</span>
                    </a>
                ))}
            </nav>
        </header>
    );
}